import{_ as l,o as i,c as a,a7 as t}from"./chunks/framework.DUCm5Bu5.js";const p=JSON.parse('{"title":"更新紀錄","description":"公開版本的日期變更紀錄。","frontmatter":{"title":"更新紀錄","description":"公開版本的日期變更紀錄。","updated":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"zh-tw/project/changelog.md","filePath":"zh-tw/project/changelog.md"}'),o={name:"zh-tw/project/changelog.md"};function c(n,e,r,d,s,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h2 id="尚未發布-—-2026-10-20-utc-08-00" tabindex="-1">尚未發布 — 2026-10-20（UTC+08:00） <a class="header-anchor" href="#尚未發布-—-2026-10-20-utc-08-00" aria-label="Permalink to &quot;尚未發布 — 2026-10-20（UTC+08:00）&quot;">​</a></h2><ul><li>每個版本都會發布 Windows x64、Windows ARM64、Linux x64 與 Linux arm64 的預先編譯套件。在 Windows 上解壓縮 ZIP 後按兩下 <code>BubbleFighter.Fantasy.Host.exe</code>：安裝助理隨即啟動並在瀏覽器中開啟，啟動出錯時錯誤會一直顯示到按下任意鍵。在 Linux 上，<code>curl -fsSL https://wasabi-fantasytaledev.github.io/install.sh | bash</code> 即可安裝伺服器，加上 <code>--docker</code> 則在容器中執行，只有再加上 <code>--with-mysql</code> 時才附帶 MySQL。</li><li>KR2026 的商店購買遵循客戶端自身商店表中的物品條款：限時物品會到期，永久物品保持永久，條款拒絕的購買會收到失敗回覆且不扣款。含有耐久計數物品的六個套裝在該版本的規則確定之前暫時無法購買。</li><li>KR2026 商店的所有封包現在都依名稱從該版本的 opcode 表查找。開啟禮物盒的已寄出清單不再觸發購買，退款請求也不再收到物品卡片的回覆。</li><li>KR2026 的新帳號現在會進入客戶端內建的角色建立畫面，與舊版本一致。KR2026 也會在玩家離線期間物品到期後顯示原生的到期通知。</li><li>修正舊版本中持有未記錄期限物品的帳號無法登入的問題，以及 cn-404、cn-406、cn-408 與 cn-706 的首次登入問題。</li><li>KR2026、cn-774 與 tw-454 改由共用的登入轉接器登入。使用自訂修補檔的營運者請注意：已移除的 <code>dialect.modern.messages</code> 登入選項列在儲存庫的 <code>CHANGELOG.md</code> 中；修補檔中仍有已移除的鍵時，啟動會失敗，刪除後即可恢復。</li><li>啟動檢查現在會驗證繫結讀寫的每個封包欄位的型別，因此封包表若改變了欄位型別，會在伺服器啟動時報錯，而不是在收到第一個封包時出錯。</li><li>疑難排解頁說明了 <code>NU1900</code> 套件稽核錯誤，以及無法連線到 nuget.org 時如何建置。</li></ul><h2 id="尚未發布-—-2026-10-18-utc-08-00" tabindex="-1">尚未發布 — 2026-10-18（UTC+08:00） <a class="header-anchor" href="#尚未發布-—-2026-10-18-utc-08-00" aria-label="Permalink to &quot;尚未發布 — 2026-10-18（UTC+08:00）&quot;">​</a></h2><ul><li>擴充四語言指南並補齊可驗證步驟：安裝與快速入門區分原始碼建置與尚未發布的建置套件；設定記錄 profile 組合、環境變數、連接埠、持久化與用戶端資料；部署涵蓋 Docker Compose、備份、升級與回復；疑難排解依「症狀 → 檢查 → 原因 → 處理」組織。</li><li>模組指南新增可實際執行的第一個模組流程；SDK 通訊協定參考新增各語言快速上手、能力協商與一致性測試內容。</li><li>重寫中英文 README，補齊環境需求、Windows 與 Linux 快速入門、Docker Compose、用戶端資料邊界與說明文件入口。</li><li>修正與目前程式碼不符的描述；尚未發布的下載與安裝入口繼續標示為即將提供。本次僅涉及說明文件，執行行為沒有改變。</li><li>新增四語言「啟動器」指南：配套 Fantasy Tale Launcher 的用戶端版本、工作階段與登入票據模型、hook 模組、散布邊界，以及面向營運者的伺服器 <code>launcher.http</code> API，包括 HTTP 426 版本閘門、JSON 相容規則與票據安全邊界。僅涉及說明文件。</li></ul><h2 id="尚未發布-—-2026-10-16-utc-08-00" tabindex="-1">尚未發布 — 2026-10-16（UTC+08:00） <a class="header-anchor" href="#尚未發布-—-2026-10-16-utc-08-00" aria-label="Permalink to &quot;尚未發布 — 2026-10-16（UTC+08:00）&quot;">​</a></h2><ul><li>加入原生事件匯流排上的宣告式 SDK 事件，支援跨語言循序/平行通知、waterfall 攔截與 bail 決策。</li><li>保留事件接續呼叫的所有權並完善 Rust 回呼清理；修正關閉時可能遺漏已記錄啟用逾時的競爭問題。</li><li>為 Python、TypeScript、Go 與 Rust 加入 SDK 服務提供者、裝飾鏈及有序服務集合，包含 Go/Rust WebAssembly。</li><li>取消與逾時後保留已進入工作的所有權，修正發布新定義後的啟用順序選擇。</li><li>模組列逾時後仍執行 SDK 清理；共用處理程序繼續執行時，允許回收已退役的啟用內容。</li><li>在模組與 SDK 指南補充註冊範例、生命週期規則及仍未實作的原生對等能力。</li></ul><h2 id="尚未發布-—-2026-10-15-utc-08-00" tabindex="-1">尚未發布 — 2026-10-15（UTC+08:00） <a class="header-anchor" href="#尚未發布-—-2026-10-15-utc-08-00" aria-label="Permalink to &quot;尚未發布 — 2026-10-15（UTC+08:00）&quot;">​</a></h2><ul><li>準備新的公開文件與 Vue 3 四語言文件站。</li><li>加入 Windows x64/ARM64 下載入口及 Linux 安裝指令碼/Docker 選項；位址仍為即將提供。</li><li>修正私有檔案排除規則，將內部工具移出公開原始碼索引。</li><li>公開驗證保留 Equipment、Shop 可獨立執行的測試，僅明確排除本機資料案例。</li><li>保留原有 bootstrap 預設值；本機目錄資料缺失時明確失敗，不再記為測試通過。</li></ul><p>這是首個公開版本的準備紀錄，不代表套件或文件站已發布。詳細變更維護在儲存庫根目錄的中英文更新紀錄。</p>',9)])])}const m=l(o,[["render",c]]);export{p as __pageData,m as default};
